package autorouter_setting

import (
	_ "embed"

	"github.com/QuantumNous/new-api/common"
	"github.com/QuantumNous/new-api/pkg/autorouter"
	"github.com/QuantumNous/new-api/setting/config"
)

// taskModelsJSON is generated by go run ./pkg/autorouter/modelrank/cmd/modelrank
// from public leaderboards; its rank_sources, task_models and default_models
// are the defaults.
//
//go:embed task_models.json
var taskModelsJSON []byte

// AutoRouterSetting configures resolution of the "auto" model. Option keys are
// autorouter_setting.<json name>; map and list values are stored as JSON.
type AutoRouterSetting struct {
	Enabled          bool   `json:"enabled"`
	JevEndpoint      string `json:"jev_endpoint"`
	JevTimeoutMs     int    `json:"jev_timeout_ms"`
	MaxRunes         int    `json:"max_runes"`
	PreviousMaxRunes int    `json:"previous_max_runes"`
	CacheTTLSeconds  int    `json:"cache_ttl_seconds"`
	// TaskModels maps a jev task type to base model names in preference order.
	// A model supports an effort when the effort-suffixed name (e.g.
	// gpt-5-high) is usable; the bare name is its provider default effort.
	TaskModels    map[string][]string `json:"task_models"`
	DefaultModels []string            `json:"default_models"`
	// RankSources records the snapshot date of every source behind the
	// current lists and when they were generated.
	RankSources map[string]string `json:"rank_sources"`
	// DifficultyEfforts maps difficulty rungs 1..n to reasoning efforts.
	DifficultyEfforts      []string `json:"difficulty_efforts"`
	DefaultEffort          string   `json:"default_effort"`
	UpgradeBenefit         float64  `json:"upgrade_benefit"`
	MinTaskTypeProbability float64  `json:"min_task_type_probability"`
	ContinuationTaskChange float64  `json:"continuation_task_change"`
}

var autoRouterSetting = AutoRouterSetting{
	JevEndpoint:            "http://hybrid-scheduling-llm-test.intsig.net/startlux-decision-27b/v1/systemone",
	JevTimeoutMs:           1000,
	MaxRunes:               2000,
	PreviousMaxRunes:       500,
	CacheTTLSeconds:        7200,
	DifficultyEfforts:      []string{"low", "medium", "high", "xhigh"},
	DefaultEffort:          "medium",
	UpgradeBenefit:         0.5,
	MinTaskTypeProbability: 0.5,
	ContinuationTaskChange: 0.5,
}

func init() {
	if err := common.Unmarshal(taskModelsJSON, &autoRouterSetting); err != nil {
		panic("autorouter_setting: task_models.json: " + err.Error())
	}
	config.GlobalConfig.Register("autorouter_setting", &autoRouterSetting)
}

func GetAutoRouterSetting() *AutoRouterSetting {
	return &autoRouterSetting
}

func (s *AutoRouterSetting) Policy() autorouter.Policy {
	return autorouter.Policy{
		TaskModels:             s.TaskModels,
		DefaultModels:          s.DefaultModels,
		DifficultyEfforts:      s.DifficultyEfforts,
		DefaultEffort:          s.DefaultEffort,
		UpgradeBenefit:         s.UpgradeBenefit,
		MinTaskTypeProbability: s.MinTaskTypeProbability,
		ContinuationTaskChange: s.ContinuationTaskChange,
	}
}
